package ro.leo.visual;
import ro.leo.i18n.L;import org.json.*;import java.io.*;import java.util.*;
public final class LexiconActivity extends PocketActivity {
 private boolean reverse;
 static JSONArray starter(){String[] ro={"apă","aer","acasă","ajutor","astăzi","autobuz","bilet","bună","carte","casă","ceas","cheie","copil","drum","fereastră","floare","frate","gară","grădină","iarnă","ieri","lapte","lumină","lună","mare","masă","mâine","mic","mulțumesc","noapte","nume","oraș","pâine","ploaie","prieten","repede","roșu","sare","soare","stradă","telefon","timp","tren","ușă","vară","verde","viață","zi"};String[] en={"water","air","home","help","today","bus","ticket","hello","book","house","clock","key","child","road","window","flower","brother","station","garden","winter","yesterday","milk","light","moon","sea","table","tomorrow","small","thank you","night","name","city","bread","rain","friend","quickly","red","salt","sun","street","phone","time","train","door","summer","green","life","day"};JSONArray out=new JSONArray();for(int i=0;i<ro.length;i++)out.put(new JSONArray().put(ro[i]).put(en[i]));return out;}
 private JSONArray words()throws Exception{JSONObject data=PocketStore.read(this,"lexicon");return data.has("words")?data.getJSONArray("words"):starter();}
 protected void render()throws Exception{list(L.t("Dicționar RO–EN"),Arrays.asList(L.t("Caută un cuvânt"),reverse?"EN → RO":"RO → EN",L.t("Importă CSV / TSV"),L.t("Adaugă traducere"),L.t("Exportă CSV"),L.t("Vocabular de pornire")+" · "+words().length()),0,new Choice(){public void pick(int at){if(at==0)search();else if(at==1){reverse=!reverse;home();}else if(at==2)chooseFile("csv|tsv|txt",1);else if(at==3)add();else if(at==4)export();else page(L.t("Dicționar offline"),L.t("Sunt incluse 48 de traduceri introductive. Poți importa până la 20.000 de perechi UTF-8, română în prima coloană și engleză în a doua. Importul înlocuiește lista după confirmare."),goHome(),"",null);}},"",null);}
 private void search(){edit(L.t("Caută"),new String[]{L.t("Cuvânt")},new String[]{""},new Saved(){public void save(String[] values)throws Exception{final String q=PocketTable.fold(values[0].trim());if(q.isEmpty())throw new IOException("Enter a word");final ArrayList<String[]> found=new ArrayList<>();job(L.t("Caută"),new Work(){public void run()throws Exception{JSONArray all=words();for(int n=0;n<all.length()&&found.size()<100;n++){JSONArray row=all.getJSONArray(n);String a=row.getString(reverse?1:0),b=row.getString(reverse?0:1);if(PocketTable.fold(a).contains(q))found.add(new String[]{a,b});}}},new Runnable(){public void run(){ArrayList<String> labels=new ArrayList<>();for(String[] row:found)labels.add(row[0]+"\n"+row[1]);list(L.t("Rezultate"),labels,0,new Choice(){public void pick(int at){final String[] row=found.get(at);page(row[0],row[1],goHome(),L.t("Învață"),new Runnable(){public void run(){try{StudyActivity.add(LexiconActivity.this,row[0],row[1]);notice(L.t("Card adăugat"));}catch(Exception e){problem(e);}}});}},"",null);back=goHome();}});}},goHome());}
 private void add(){edit(L.t("Traducere nouă"),new String[]{"Română","English"},new String[]{"",""},new Saved(){public void save(String[] v)throws Exception{if(v[0].trim().isEmpty()||v[1].trim().isEmpty())throw new IOException("Both columns required");JSONArray rows=words();if(rows.length()>=20000)throw new IOException("Limit: 20000");rows.put(new JSONArray().put(v[0].trim()).put(v[1].trim()));PocketStore.write(LexiconActivity.this,"lexicon",new JSONObject().put("words",rows));home();}},goHome());}
 protected void selectedFile(int request,final File file){final ArrayList<String[]> imported=new ArrayList<>();job(L.t("Import în curs"),new Work(){public void run()throws Exception{imported.addAll(PocketTable.parse(PocketStore.fileBytes(file,2*1024*1024),20000));if(imported.isEmpty())throw new IOException("Empty dictionary");}},new Runnable(){public void run(){options(L.t("Înlocuiești dicționarul?"),new String[]{L.t("Păstrează"),L.t("Importă")+" · "+imported.size()},new Choice(){public void pick(int at){if(at==1)job(L.t("Import în curs"),new Work(){public void run()throws Exception{JSONArray rows=new JSONArray();for(String[] pair:imported)rows.put(new JSONArray().put(pair[0]).put(pair[1]));PocketStore.write(LexiconActivity.this,"lexicon",new JSONObject().put("words",rows));}},goHome());else home();}});}});}
 private void export(){job(L.t("Export dicționar"),new Work(){public void run()throws Exception{StringBuilder text=new StringBuilder();JSONArray all=words();for(int i=0;i<all.length();i++)text.append(PocketStore.csv(all.getJSONArray(i).getString(0))).append(',').append(PocketStore.csv(all.getJSONArray(i).getString(1))).append('\n');File out=PocketStore.output(LexiconActivity.this,"Dictionary","ro-en.csv");BackupEngine.write(out,text.toString().getBytes("UTF-8"));last=out;}},new Runnable(){public void run(){exported(last);}});}private File last;
}
